import java.util.*;

class Solution {
    public int[] decompressRLElist(int[] nums) {
        List<Integer> values = new ArrayList<>();
        for (int i = 0; i < nums.length; i += 2) {
            int freq = nums[i];
            int value = nums[i + 1];
            for (int count = 0; count < freq; count++) {
                values.add(value);
            }
        }

        int[] ans = new int[values.size()];
        for (int i = 0; i < values.size(); i++) {
            ans[i] = values.get(i);
        }
        return ans;
    }
}

